package com.chesspulseai.service; import com.chesspulseai.engine.EngineEvaluation; import com.chesspulseai.enumtype.PlayerColor; import org.springframework.stereotype.Service;
@Service public class CoachingService { public String explain(PlayerColor player,EngineEvaluation e){if(e.mateScore()!=null)return "The engine sees a forced mate "+(e.mateScore()>0?"for White":"for Black")+". Examine the principal variation carefully.";if(e.centipawns()==null)return "Engine evaluation is unavailable for this position.";double pawns=Math.abs(e.centipawns())/100d;String side=e.centipawns()>0?"White":"Black";String lead=pawns<0.35?"The position remains close.":side+" has a "+String.format("%.1f",pawns)+" pawn-equivalent advantage.";return lead+" The engine’s preferred continuation is "+(e.bestMove()==null?"not available":e.bestMove())+"; compare it with the played move to identify the practical improvement.";}}

